window.WORD_AI_EXAMPLE_CHUNK = {"entries":{"invent":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"发明"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"创作"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"虚构"}],"examples":[{"sentence":"Thomas Edison invented the phonograph, which revolutionized the way people experienced music.","translation":"托马斯·爱迪生发明了留声机，它彻底改变了人们体验音乐的方式。","targetForm":"invented","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Engineers are striving to invent a more efficient battery that can store renewable energy for longer periods.","translation":"工程师们正在努力发明一种更高效的电池，能够更长时间地储存可再生能源。","targetForm":"invent","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The author invented a complex fantasy world where magic and technology coexist in delicate balance.","translation":"作者创作了一个复杂的奇幻世界，在那里魔法与技术以微妙的平衡共存。","targetForm":"invented","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"He invented an elaborate excuse about a traffic jam to justify his late arrival at the meeting.","translation":"他编造了一个关于交通堵塞的精心借口，来为他开会迟到辩解。","targetForm":"invented","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"To avoid punishment, the child invented a story about a stray dog eating his homework.","translation":"为了逃避惩罚，那个孩子虚构了一个关于流浪狗吃掉他作业的故事。","targetForm":"invented","senseId":"source-v-3","sourceSenseId":"v-3"}]},"invasion":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"侵犯"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"侵入"},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"[医] 侵袭","contextReviewed":true},{"id":"source-n-5","partOfSpeech":"n.","sourceSenseIds":["n-5"],"sense":"发病","contextReviewed":true}],"examples":[{"sentence":"The invasion of privacy by unauthorized data collection has become a major concern in the digital age, as personal information is increasingly commodified.","translation":"未经授权的数据收集对隐私的侵犯已成为数字时代的一大担忧，因为个人信息日益商品化。","targetForm":"invasion","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The military invasion of the neighboring country drew widespread international condemnation, yet the aggressor remained defiant.","translation":"对邻国的军事入侵招致了广泛的国际谴责，然而侵略者依然我行我素。","targetForm":"invasion","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The invasion of non-native species often disrupts local ecosystems and threatens biodiversity, which can lead to irreversible ecological damage.","translation":"外来物种的侵入常常破坏当地生态系统，威胁生物多样性，这可能导致不可逆转的生态破坏。","targetForm":"invasion","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The invasion of cancer cells into surrounding tissues marks a critical stage in tumor progression, after which metastasis becomes more likely.","translation":"癌细胞向周围组织的侵袭标志着肿瘤发展的关键阶段，此后转移的可能性更大。","targetForm":"invasion","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"The sudden invasion of symptoms suggested an acute onset of the disease, prompting immediate medical intervention.","translation":"症状的突然发作表明疾病急性起病，需要立即进行医疗干预。","targetForm":"invasion","senseId":"source-n-5","sourceSenseId":"n-5"}]},"inward":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"内心的"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"向内的"}],"examples":[{"sentence":"Her inward confidence remained steady despite the hostile questions raised during the scholarship interview.","translation":"尽管奖学金面试中出现了尖锐的质疑，她内心的自信依然坚定。","targetForm":"inward","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The long walk gave her time for inward reflection before she answered the difficult question.","translation":"漫长的步行让她有时间进行内省，然后才回答那个棘手的问题。","targetForm":"inward","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Engineers detected an inward movement of the retaining wall after several days of unusually heavy rain.","translation":"连续数日遭遇异常强降雨后，工程师发现挡土墙出现了向内位移。","targetForm":"inward","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"The designer gave the cabinet inward folding doors to preserve space in the narrow corridor.","translation":"设计师为橱柜采用了向内折叠的柜门，以节省狭窄走廊的空间。","targetForm":"inward","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"The inward curve of the roof channels rainwater toward a drain below the courtyard.","translation":"屋顶向内的弧度把雨水导向庭院下方的排水口。","targetForm":"inward","senseId":"source-adj-2","sourceSenseId":"adj-2"}]},"intact":{"senseGroups":[{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"完整的"}],"examples":[{"sentence":"Despite the severe earthquake, the historic library remained largely intact and preserved centuries of knowledge.","translation":"尽管发生严重地震，这座历史图书馆仍基本完好，保存了数百年的知识。","targetForm":"intact","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"The research team ensured that the original data stayed intact throughout the complex analysis.","translation":"研究团队确保原始数据在复杂分析过程中保持完整。","targetForm":"intact","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"Because the capsule could withstand extreme pressure, its contents were recovered intact from the ocean floor.","translation":"由于这个密封舱能承受极端压力，其中的物品从海底打捞出来时完好无损。","targetForm":"intact","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"The legal framework must remain intact if public trust in the judicial system is to endure.","translation":"如果要维持公众对司法体系的信任，法律框架必须保持完整。","targetForm":"intact","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"Even after the merger, the company's core values were kept intact, which reassured long-term employees.","translation":"即使在合并后，这家公司的核心价值观仍被完整保留，这让长期员工感到安心。","targetForm":"intact","senseId":"source-adj-3","sourceSenseId":"adj-3"}]},"input":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"输入"}],"examples":[{"sentence":"Although the manager made the final decision, she valued input from every team member before choosing a solution.","translation":"尽管经理作出最终决定，她在选择方案前仍重视每一位团队成员的意见。","targetForm":"input","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because the project crosses several disciplines, the coordinator sought input from experts in design, engineering, and finance.","translation":"由于项目涉及多个学科，协调员征求了设计、工程和财务专家的意见。","targetForm":"input","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"When developing public policy, governments should consider input from citizens in order to reflect diverse needs.","translation":"制定公共政策时，政府应考虑公民意见，以反映多样化需求。","targetForm":"input","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The software needs little user input, which makes it accessible to people with limited technical experience.","translation":"该软件只需很少的用户输入，这让技术经验有限的人也能使用。","targetForm":"input","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"If the committee ignores expert input, the regulations may fail to address essential safety concerns.","translation":"如果委员会忽视专家意见，相关规定可能无法解决关键安全问题。","targetForm":"input","senseId":"source-n-1","sourceSenseId":"n-1"}]},"investigate":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"调查"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"审查"}],"examples":[{"sentence":"The regulatory agency was created to investigate financial fraud and protect investors from unethical practices.","translation":"成立该监管机构是为了调查金融欺诈，并保护投资者免受不道德行为侵害。","targetForm":"investigate","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Because the first experiment produced inconsistent results, the team investigated the method for possible flaws.","translation":"由于最初实验结果不一致，团队调查了方法中可能存在的缺陷。","targetForm":"investigated","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Although the company denied wrongdoing, an independent panel was appointed to investigate the allegations thoroughly.","translation":"尽管公司否认有不当行为，仍任命了独立小组彻底调查相关指控。","targetForm":"investigate","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"To protect public health, officials must investigate the source of an outbreak before it spreads further.","translation":"为保护公共健康，官员必须在疫情进一步蔓延前调查其源头。","targetForm":"investigate","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"When scientists observe a new phenomenon, they investigate its underlying mechanisms through systematic experiments.","translation":"科学家观察到新现象时，会通过系统实验调查其潜在机制。","targetForm":"investigate","senseId":"source-v-1","sourceSenseId":"v-1"}]},"insult":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"侮辱"}],"examples":[{"sentence":"Although the comment was intended as a joke, many perceived it as a direct insult to their cultural traditions.","translation":"尽管这句话本意是开玩笑，但许多人认为这是对他们文化传统的直接侮辱。","targetForm":"insult","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because the manager publicly criticized her work without justification, she felt a deep sense of insult and considered resigning.","translation":"由于经理毫无道理地公开批评她的工作，她感到深受侮辱并考虑辞职。","targetForm":"insult","senseId":"source-n-1","sourceSenseId":"n-1"}]},"intend":{"senseGroups":[{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"意思是"}],"examples":[{"sentence":"Moreover, when economists adjust their message to fit their audience, the result is the opposite of what is intended: they rapidly lose credibility.","translation":"此外，当经济学家根据受众来调整信息时，往往会取得截然相反的效果：他们会以惊人的速度丧失公信力。","targetForm":"intended","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"And, third, laws intended to protect private information should be reevaluated to ensure that IT companies are unable to profit from exploiting and manipulating it.","translation":"最重要的是，公众必须更加深刻地理解IT的经济效应，特别是改善了如此多的人的生活的技术如何只让如此少的人致富。","targetForm":"intended","senseId":"source-v-3","sourceSenseId":"v-3"}]},"infect":{"senseGroups":[{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"感染"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"传染"}],"examples":[{"sentence":"Misinformation can infect public discourse, eroding trust in institutions and thereby weakening the foundations of democracy.","translation":"错误信息会侵蚀公共讨论，削弱对机构的信任，从而动摇民主的基础。","targetForm":"infect","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"A leader's negative attitude can infect the entire team, lowering morale and productivity even when external conditions are favorable.","translation":"领导者的消极态度会感染整个团队，即使外部条件有利，也会降低士气和生产力。","targetForm":"infect","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Because the virus can infect unvaccinated individuals rapidly, public health campaigns emphasize the importance of immunization to ensure herd immunity.","translation":"由于病毒能迅速感染未接种疫苗的人，公共卫生运动强调免疫接种的重要性以确保群体免疫。","targetForm":"infect","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"If a wound is not properly cleaned, bacteria can infect it and cause severe complications, which may require surgical intervention.","translation":"如果伤口未得到适当清洁，细菌会感染它并引起严重并发症，可能需要手术干预。","targetForm":"infect","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"When a computer lacks robust security measures, malware can infect the system and compromise sensitive data, which often leads to financial loss.","translation":"当计算机缺乏强大的安全措施时，恶意软件会感染系统并危及敏感数据，这常常导致经济损失。","targetForm":"infect","senseId":"source-v-2","sourceSenseId":"v-2"}]},"intervene":{"senseGroups":[{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"调停"},{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"[经] 进场干预","contextReviewed":true},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"插入"}],"examples":[{"sentence":"The government decided to intervene in the labor dispute to prevent a prolonged strike that could disrupt the national economy.","translation":"政府决定介入劳资纠纷，以防止可能扰乱国民经济的长期罢工。","targetForm":"intervene","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"When the two colleagues began arguing loudly, the manager intervened and calmly mediated their disagreement.","translation":"当两位同事开始大声争吵时，经理介入并冷静地调解了他们的分歧。","targetForm":"intervened","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The central bank is intervening in the foreign exchange market to stabilize the rapidly depreciating currency.","translation":"中央银行正在干预外汇市场，以稳定迅速贬值的货币。","targetForm":"intervening","senseId":"source-v-4","sourceSenseId":"v-4"},{"sentence":"A decade of relative peace intervened between the two conflicts, allowing the region to rebuild its infrastructure.","translation":"两次冲突之间相隔了十年的相对和平，使该地区得以重建其基础设施。","targetForm":"intervened","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Several months intervened before the committee reconvened to review the revised proposal, which had undergone significant changes.","translation":"几个月过去了，委员会才重新开会审查经过重大修改的提案。","targetForm":"intervened","senseId":"source-v-1","sourceSenseId":"v-1"}]},"installation":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"安装"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"装置"}],"examples":[{"sentence":"Although installation of the security system was costly, it reduced the risk of unauthorised access.","translation":"尽管安装安全系统成本高昂，它仍降低了未经授权访问的风险。","targetForm":"installation","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The company completed installation of the machinery early, which allowed production to start ahead of schedule.","translation":"公司提前完成机械安装，使生产得以早于计划开始。","targetForm":"installation","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because installation requires specialised tools, only certified technicians may carry out the work.","translation":"由于安装需要专用工具，只有认证技术人员可以进行这项工作。","targetForm":"installation","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The art installation uses interactive light projections to explore the relationship between technology and nature.","translation":"这件艺术装置使用互动光影投影，探索技术与自然的关系。","targetForm":"installation","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Proper installation of the software is essential if every feature is to operate correctly and securely.","translation":"如果要让每项功能正确且安全运行，正确安装软件至关重要。","targetForm":"installation","senseId":"source-n-1","sourceSenseId":"n-1"}]},"increase":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"增加"}],"examples":[{"sentence":"Oil production does not matter; exports do, which means that announcements of increases in oil output are irrelevant for prices.","translation":"这表明OPEC成员国国和石油进口国的政策制定者们都不应该忘记：应对高油价的唯一方法就是维持高油价。","targetForm":"increases","senseId":"source-n-1","sourceSenseId":"n-1"}]},"inherent":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"固有的"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"与生俱来的"}],"examples":[{"sentence":"The inherent complexity of climate systems makes accurate long-term predictions extremely challenging, because numerous variables interact in nonlinear ways.","translation":"气候系统固有的复杂性使得准确的长期预测极具挑战性，因为众多变量以非线性方式相互作用。","targetForm":"inherent","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Because language has an inherent connection to cultural identity, preserving minority languages is essential for cultural diversity, which enriches global heritage.","translation":"由于语言与文化认同有着固有的联系，保护少数民族语言对于文化多样性至关重要，这丰富了全球遗产。","targetForm":"inherent","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Despite its inherent risks, nuclear energy remains a low-carbon alternative to fossil fuels, which can help mitigate climate change if managed safely.","translation":"尽管存在固有的风险，核能仍然是化石燃料的一种低碳替代方案，如果安全管理，它有助于缓解气候变化。","targetForm":"inherent","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Every individual possesses inherent dignity that must be respected by society and the law, which is a fundamental principle of human rights.","translation":"每个人都拥有固有的尊严，必须受到社会与法律的尊重，这是人权的一项基本原则。","targetForm":"inherent","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"The inherent flexibility of online learning allows students to balance education with work and family responsibilities, thereby increasing access to higher education.","translation":"在线学习固有的灵活性使学生能够平衡教育与工作和家庭责任，从而增加了接受高等教育的机会。","targetForm":"inherent","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"independent":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"独立的"},{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"不须依赖的"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"无党派者"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"有主见的"}],"examples":[{"sentence":"The study was reviewed by an independent panel with no financial connection to the company.","translation":"该研究由与公司不存在经济关联的独立小组审查。","targetForm":"independent","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"She became more independent after learning to manage her budget and schedule.","translation":"学会管理预算和日程后，她变得更加独立。","targetForm":"independent","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"An independent bookstore can reflect the reading interests of its local community.","translation":"独立书店能反映当地社区的阅读兴趣。","targetForm":"independent","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The independent supported the proposal after comparing it with several alternatives.","translation":"这名无党派人士将该提案与多个替代方案比较后表示支持。","targetForm":"independent","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Independent thinkers test familiar ideas instead of accepting them without evidence.","translation":"独立思考者会检验熟悉的观点，而非毫无证据地接受它们。","targetForm":"Independent","senseId":"source-adj-2","sourceSenseId":"adj-2"}]},"indication":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"暗示"}],"examples":[{"sentence":"His victory at this age in an international competition is a good indication of a bright future.","translation":"他现在这个年纪，就已经在国际比赛中取胜，前途实在无可限量。","targetForm":"indication","senseId":"source-n-3","sourceSenseId":"n-3"}]},"indifferent":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"漠不关心的"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"无重要性的"},{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"中立的"},{"id":"source-adj-5","partOfSpeech":"adj.","sourceSenseIds":["adj-5"],"sense":"无作用的","contextReviewed":true}],"examples":[{"sentence":"Although the evidence was compelling, several officials remained indifferent to the residents' repeated complaints.","translation":"尽管证据很有说服力，几名官员对居民一再提出的投诉仍漠不关心。","targetForm":"indifferent","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"For the calculation, it was indifferent whether the figures were copied from the first backup or the second.","translation":"对这项计算而言，数据是从第一份还是第二份备份中复制并不重要。","targetForm":"indifferent","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"A fair referee must remain indifferent to the fame of either team while applying the rules.","translation":"公正的裁判在执行规则时必须不偏袒任何一支因名气更大而受关注的队伍。","targetForm":"indifferent","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"When managers appear indifferent to staff concerns, small frustrations can develop into lasting mistrust.","translation":"当管理者显得对员工关切漠不关心时，小小的挫折可能演变为长期的不信任。","targetForm":"indifferent","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The colour of the storage boxes was indifferent to safety, whereas their labels and seals were essential.","translation":"储物箱的颜色与安全无关，而它们的标签和封条却至关重要。","targetForm":"indifferent","senseId":"source-adj-5","sourceSenseId":"adj-5"}]},"instruction":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"指令"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"教导"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"命令"}],"examples":[{"sentence":"Before assembling the device, read each instruction carefully so that the small parts are not fitted in the wrong order.","translation":"组装设备前，请仔细阅读每一条说明，以免小零件装错顺序。","targetForm":"instruction","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Effective instruction in argument writing teaches students to support claims with precise and relevant evidence.","translation":"有效的议论文写作教学会教学生用准确且相关的证据支撑观点。","targetForm":"instruction","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Under explicit instruction from the safety officer, the crew suspended work until the inspection was complete.","translation":"在安全主管的明确命令下，工作人员暂停作业，直到检查完成。","targetForm":"instruction","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The museum provides an audio instruction at the entrance for visitors who prefer to follow the exhibition independently.","translation":"博物馆在入口提供语音指引，供希望自主参观展览的游客使用。","targetForm":"instruction","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because online instruction can feel impersonal, the course includes live discussions in which students test their ideas.","translation":"由于在线教学可能显得缺少人情味，课程安排了实时讨论，让学生检验自己的想法。","targetForm":"instruction","senseId":"source-n-2","sourceSenseId":"n-2"}]},"ingenious":{"senseGroups":[{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"精巧的"},{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"灵敏的"}],"examples":[{"sentence":"The engineer devised an ingenious solution that reduced energy consumption by half.","translation":"工程师设计了一个巧妙的解决方案，将能耗降低了一半。","targetForm":"ingenious","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"Her ingenious use of recycled materials transformed waste into beautiful sculptures.","translation":"她巧妙地利用回收材料，将废物变成了美丽的雕塑。","targetForm":"ingenious","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"The detective admired the criminal's ingenious method of bypassing the security system.","translation":"侦探对罪犯绕过安全系统的巧妙方法感到钦佩。","targetForm":"ingenious","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"An ingenious network of canals allowed the ancient city to thrive in a desert environment.","translation":"一个精巧的运河网络使这座古城在沙漠环境中繁荣发展。","targetForm":"ingenious","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"The young inventor's ingenious mind constantly generated ideas for new gadgets.","translation":"这位年轻发明家灵敏的头脑不断产生新装置的创意。","targetForm":"ingenious","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"inflation":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"通货膨胀"}],"examples":[{"sentence":"Inflation targeting has other effects, too, which seem to be more on the minds of central bankers.","translation":"通胀目标还有其他影响，其中对央行官员思维的影响更大。","targetForm":"inflation","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Others, especially on the political right, worried that the latest monetary measures would fuel future inflation and encourage unbridled government spending.","translation":"其他人，特别是政治右翼，担心最近的货币措施会助长未来通胀、鼓励不受约束的政府支出。","targetForm":"inflation","senseId":"source-n-3","sourceSenseId":"n-3"}]},"intermittent":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"间歇的"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"断断续续的"}],"examples":[{"sentence":"Intermittent fasting, which alternates between eating and fasting periods, has been studied for its potential metabolic benefits.","translation":"间歇性禁食在进食和禁食时段之间交替，因其潜在的代谢益处而受到研究。","targetForm":"intermittent","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Although the region experiences intermittent rainfall, farmers have developed effective water conservation methods to sustain crops.","translation":"尽管该地区降雨时断时续，但农民们已开发出有效的节水方法来维持作物生长。","targetForm":"intermittent","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"Because intermittent network failures disrupted remote work, the company invested in a more reliable infrastructure.","translation":"由于间歇性的网络故障扰乱了远程工作，该公司投资建设了更可靠的基础设施。","targetForm":"intermittent","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Despite intermittent setbacks, the research team persisted, ultimately achieving a breakthrough in renewable energy storage.","translation":"尽管遭遇间歇性的挫折，研究团队坚持不懈，最终在可再生能源存储方面取得了突破。","targetForm":"intermittent","senseId":"source-adj-2","sourceSenseId":"adj-2"}]},"incur":{"senseGroups":[{"id":"source-v-5","partOfSpeech":"v.","sourceSenseIds":["v-5"],"sense":"担负；产生（费用、债务等）","contextReviewed":true},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"招致"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"蒙受"}],"examples":[{"sentence":"Companies that ignore environmental rules may incur heavy fines as well as lasting damage to their reputation.","translation":"无视环境法规的公司可能招致巨额罚款，并对声誉造成长期损害。","targetForm":"incur","senseId":"source-v-5","sourceSenseId":"v-5"},{"sentence":"By delaying repairs, the council incurred the anger of residents whose homes had been flooded repeatedly.","translation":"由于拖延维修，市政委员会招致了那些住房多次被淹居民的愤怒。","targetForm":"incurred","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Although the expedition succeeded, the team incurred severe hardship during the weeks when supplies could not reach them.","translation":"尽管考察成功了，团队在补给无法送达的几周里仍蒙受了严重艰苦。","targetForm":"incurred","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The project will incur substantial initial costs, so its long-term benefits must be assessed realistically.","translation":"该项目将产生大量初始成本，因此必须现实地评估其长期收益。","targetForm":"incur","senseId":"source-v-5","sourceSenseId":"v-5"},{"sentence":"Students who return library books late may incur a fee unless they renew them online before the deadline.","translation":"学生若未在截止日前在线续借，逾期归还图书可能会产生费用。","targetForm":"incur","senseId":"source-v-5","sourceSenseId":"v-5"}]},"incorporate":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"吸收"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"使组成公司"}],"examples":[{"sentence":"The architect decided to incorporate sustainable materials into the design of the new library, which reduced the building's carbon footprint significantly.","translation":"建筑师决定将可持续材料融入新图书馆的设计中，这显著降低了建筑的碳足迹。","targetForm":"incorporate","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The company was incorporated in 1995 and has since grown into a multinational corporation with offices in over twenty countries.","translation":"该公司于1995年注册成立，此后发展成为一家在二十多个国家设有办事处的跨国公司。","targetForm":"incorporated","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"The research team incorporated feedback from peer reviewers to strengthen the final manuscript before submission.","translation":"研究团队吸收了同行评审的反馈，以在提交前加强最终稿件。","targetForm":"incorporated","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The new policy incorporates several recommendations from the advisory committee, ensuring a comprehensive approach to urban planning.","translation":"新政策采纳了咨询委员会的多项建议，确保城市规划的全面性。","targetForm":"incorporates","senseId":"source-v-1","sourceSenseId":"v-1"}]},"invariably":{"senseGroups":[{"id":"source-adv-3","partOfSpeech":"adv.","sourceSenseIds":["adv-3"],"sense":"始终如一地"}],"examples":[{"sentence":"Students who postpone their assignments until the last minute invariably produce work that falls short of their potential.","translation":"将作业拖到最后一刻的学生，其成果总是未能充分发挥他们的潜力。","targetForm":"invariably","senseId":"source-adv-3","sourceSenseId":"adv-3"},{"sentence":"When researchers rely on a single data source, their conclusions invariably suffer from limited generalizability.","translation":"当研究人员依赖单一数据来源时，其结论的普适性总是会受到限制。","targetForm":"invariably","senseId":"source-adv-3","sourceSenseId":"adv-3"},{"sentence":"In competitive markets, firms that fail to innovate invariably lose their advantage over time.","translation":"在竞争性市场中，未能创新的企业随着时间的推移总是会失去优势。","targetForm":"invariably","senseId":"source-adv-3","sourceSenseId":"adv-3"}]},"inhale":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"吸入"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"吸气"}],"examples":[{"sentence":"The nurse showed the patient how to inhale the medication slowly so that it could reach the lungs effectively.","translation":"护士向患者示范如何缓慢吸入药物，以便药物能够有效进入肺部。","targetForm":"inhale","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Because firefighters may inhale toxic fumes during rescue work, they wear breathing equipment that supplies clean air.","translation":"由于消防员在救援工作中可能吸入有毒烟雾，他们会佩戴提供清洁空气的呼吸设备。","targetForm":"inhale","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"When people inhale pollen in spring, an overactive immune response can trigger symptoms of asthma.","translation":"人们春季吸入花粉时，过度活跃的免疫反应可能引发哮喘症状。","targetForm":"inhale","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The instructor asked the class to inhale through the nose before exhaling slowly through the mouth.","translation":"教练要求全班先用鼻子吸气，再缓慢用嘴呼气。","targetForm":"inhale","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Workers who inhale silica dust without adequate protection risk developing a serious and irreversible lung disease.","translation":"没有充分防护便吸入硅尘的工人，可能患上严重且不可逆的肺部疾病。","targetForm":"inhale","senseId":"source-v-1","sourceSenseId":"v-1"}]},"investment":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"投资"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"包埋料；围模料；包埋法","contextReviewed":true}],"examples":[{"sentence":"Investment in reliable public transport can reduce congestion while improving access to employment.","translation":"对可靠公共交通的投资可以减少拥堵，同时改善就业可达性。","targetForm":"Investment","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the initial investment was large, the library saved money through lower energy use.","translation":"尽管初始投资很大，图书馆仍通过降低能耗节省了资金。","targetForm":"investment","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because the fund spread its investment across several sectors, it was less exposed to sudden losses.","translation":"由于该基金把投资分散到多个行业，它较少受到突发损失的影响。","targetForm":"investment","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The laboratory prepared an investment around the sample before casting the final metal component.","translation":"实验室在浇铸最终金属部件前，先在样品周围制备了包埋料。","targetForm":"investment","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"When governments increase investment in early education, communities benefit for decades afterwards.","translation":"当政府增加对早期教育的投入时，社区会在此后数十年持续受益。","targetForm":"investment","senseId":"source-n-1","sourceSenseId":"n-1"}]},"industrialize":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"使工业化"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"实现工业化"}],"examples":[{"sentence":"Although the government attempted to industrialize the rural area through tax incentives, the lack of skilled labor hindered progress significantly.","translation":"尽管政府试图通过税收优惠使农村地区工业化，但缺乏熟练劳动力严重阻碍了进展。","targetForm":"industrialize","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Because the nation chose to industrialize without enforcing environmental regulations, its rivers became so polluted that aquatic life nearly vanished.","translation":"由于该国选择工业化而不执行环境法规，其河流受到严重污染，水生生物几乎消失。","targetForm":"industrialize","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"If a country fails to industrialize its economy, it may remain dependent on volatile commodity exports, thereby exposing itself to frequent financial crises.","translation":"如果一个国家未能使其经济工业化，它可能仍然依赖不稳定的商品出口，从而使其面临频繁的金融危机。","targetForm":"industrialize","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"While many economists argue that developing countries must industrialize to escape poverty, others warn that automation reduces the job creation once associated with manufacturing.","translation":"尽管许多经济学家认为发展中国家必须工业化以摆脱贫困，但其他人警告说，自动化减少了曾经与制造业相关的就业机会。","targetForm":"industrialize","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The decision to industrialize the coastal region, which had relied on fishing for centuries, sparked protests from local communities who feared losing their cultural heritage.","translation":"将沿海地区工业化的决定引发了当地社区的抗议，该地区几个世纪以来一直依赖渔业，他们担心失去文化遗产。","targetForm":"industrialize","senseId":"source-v-1","sourceSenseId":"v-1"}]},"insurance":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"保险"}],"examples":[{"sentence":"Waiting until October for the next move up is like buying insurance against a catastrophic loss.","translation":"等到十月份在决定下一步就像是为防止灾难性的损失而购买保险。","targetForm":"insurance","senseId":"source-n-1","sourceSenseId":"n-1"}]},"instant":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"瞬间"},{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"即时的"},{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"紧急的"}],"examples":[{"sentence":"The instant the earthquake struck, the building's structural integrity was compromised beyond repair.","translation":"地震发生的那一瞬间，建筑物的结构完整性就遭到了不可修复的破坏。","targetForm":"instant","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"For a fleeting instant, the diplomat's composure wavered as the unexpected question was posed.","translation":"在那个短暂的瞬间，当意外的问题被提出时，这位外交官的镇定动摇了。","targetForm":"instant","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The new software provides instant access to a vast repository of academic journals, which greatly facilitates research.","translation":"新软件提供了对大量学术期刊库的即时访问，这极大地便利了研究。","targetForm":"instant","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"The patient's condition demanded instant medical intervention to prevent irreversible neurological damage.","translation":"病人的状况需要紧急医疗干预，以防止不可逆的神经损伤。","targetForm":"instant","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Modern consumers have grown accustomed to the instant gratification provided by on-demand streaming services.","translation":"现代消费者已经习惯了按需流媒体服务所提供的即时满足感。","targetForm":"instant","senseId":"source-adj-3","sourceSenseId":"adj-3"}]},"intersection":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"十字路口"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"交叉点"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"交集"}],"examples":[{"sentence":"The new traffic lights at the busy intersection have significantly reduced the number of accidents during peak hours.","translation":"繁忙十字路口的新交通信号灯显著减少了高峰时段的事故数量。","targetForm":"intersection","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The intersection of these two major fault lines makes the region particularly susceptible to seismic activity.","translation":"这两条主要断层线的交叉点使得该地区特别容易受到地震活动的影响。","targetForm":"intersection","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The research lies at the intersection of cognitive psychology and artificial intelligence, yielding novel insights into learning processes.","translation":"这项研究处于认知心理学和人工智能的交集，为学习过程提供了新颖的见解。","targetForm":"intersection","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The policy addresses the critical intersection of public health and economic stability during the pandemic recovery phase.","translation":"该政策应对了疫情恢复阶段公共卫生与经济稳定之间的关键交集。","targetForm":"intersection","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"A thorough analysis of the intersection between cultural norms and legal frameworks is essential for effective governance.","translation":"对文化规范与法律框架之间交集的透彻分析对于有效治理至关重要。","targetForm":"intersection","senseId":"source-n-1","sourceSenseId":"n-1"}]},"intrinsic":{"senseGroups":[{"id":"source-adj-5","partOfSpeech":"adj.","sourceSenseIds":["adj-5"],"sense":"内在的","contextReviewed":true},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"原有的"},{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"真正的"}],"examples":[{"sentence":"The intrinsic value of education lies not merely in career preparation but in fostering critical thinking and empathy.","translation":"教育的内在价值不仅在于职业准备，更在于培养批判性思维和同理心。","targetForm":"intrinsic","senseId":"source-adj-5","sourceSenseId":"adj-5"},{"sentence":"Scientists argue that curiosity is an intrinsic human trait that drives exploration and innovation from childhood onward.","translation":"科学家认为，好奇心是人类固有的特质，从童年起就驱动着探索和创新。","targetForm":"intrinsic","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"The artist sought to capture the intrinsic beauty of the natural landscape, which she believed transcended superficial appearances.","translation":"那位艺术家试图捕捉自然景观的真正之美，她认为这超越了表面的外观。","targetForm":"intrinsic","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"A material's intrinsic properties, such as density and thermal conductivity, determine its suitability for engineering applications.","translation":"材料的固有属性，如密度和导热性，决定了其在工程应用中的适用性。","targetForm":"intrinsic","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"The philosopher contended that morality has an intrinsic basis in human reason, independent of cultural norms or divine command.","translation":"那位哲学家主张，道德在人类理性中具有内在基础，独立于文化规范或神命。","targetForm":"intrinsic","senseId":"source-adj-5","sourceSenseId":"adj-5"}]},"invisible":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"看不见的"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"无形的"}],"examples":[{"sentence":"Although the benefits of regular exercise are invisible in the short term, they significantly reduce long-term health risks.","translation":"尽管定期锻炼的好处短期内看不见，但它们能显着降低长期健康风险。","targetForm":"invisible","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The gradual erosion of privacy is an invisible process that only becomes apparent when personal data is misused.","translation":"隐私的逐渐侵蚀是一个看不见的过程，只有当个人数据被滥用时才会变得明显。","targetForm":"invisible","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"While the digital divide remains invisible to many urban residents, it severely limits educational opportunities in rural areas.","translation":"尽管数字鸿沟对许多城市居民来说仍然是看不见的，但它严重限制了农村地区的教育机会。","targetForm":"invisible","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Because emotional labor is often invisible, its contribution to workplace harmony is frequently undervalued.","translation":"由于情绪劳动常常是看不见的，它对职场和谐的贡献经常被低估。","targetForm":"invisible","senseId":"source-adj-2","sourceSenseId":"adj-2"}]},"individual":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"个人"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"个体"},{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"个别的"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"个人的"},{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"独特的"}],"examples":[{"sentence":"Although an individual can make a difference, lasting change often requires cooperation across the community.","translation":"尽管个人能够带来改变，持久的变化往往需要整个社区的合作。","targetForm":"individual","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The policy protects each individual by explaining clearly how personal information will be used.","translation":"该政策通过清楚说明个人信息将如何使用来保护每个个体。","targetForm":"individual","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"When teachers notice individual strengths, they can give students more useful feedback.","translation":"当教师注意到个别优势时，他们能给学生更有用的反馈。","targetForm":"individual","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Because each person has an individual learning style, one method may not suit every student.","translation":"由于每个人都有个人的学习方式，一种方法未必适合每位学生。","targetForm":"individual","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"The artist's individual approach combined local traditions with a modern use of colour.","translation":"这位艺术家独特的方式把当地传统与现代色彩运用结合起来。","targetForm":"individual","senseId":"source-adj-3","sourceSenseId":"adj-3"}]},"indoor":{"senseGroups":[{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"室内的"}],"examples":[{"sentence":"Public health experts recommend improving indoor ventilation systems, which can significantly reduce the transmission of respiratory viruses.","translation":"公共卫生专家建议改善室内通风系统，这可以显着减少呼吸道病毒的传播。","targetForm":"indoor","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"The new office design emphasizes indoor greenery, which not only enhances aesthetics but also improves employee well-being.","translation":"新的办公室设计强调室内绿化，这不仅提升了美感，还改善了员工的幸福感。","targetForm":"indoor","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"Because the outdoor air quality was hazardous, the school relocated all physical education classes to the indoor gymnasium.","translation":"由于室外空气质量有害，学校将所有体育课转移到室内体育馆。","targetForm":"indoor","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"To minimize energy loss, the building uses advanced insulation that maintains a stable indoor temperature throughout the year.","translation":"为了最大限度地减少能量损失，该建筑采用先进的隔热材料，全年保持稳定的室内温度。","targetForm":"indoor","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"Although the conference was originally planned for the garden, unexpected rain forced the organizers to move it to an indoor venue.","translation":"尽管会议原计划在花园举行，但突如其来的降雨迫使组织者将其移至室内场地。","targetForm":"indoor","senseId":"source-adj-2","sourceSenseId":"adj-2"}]},"instrumental":{"senseGroups":[{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"可作为手段的"},{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"仪器的"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"器具的"}],"examples":[{"sentence":"Early childhood education is instrumental in shaping cognitive and social development that continues into adult life.","translation":"早期教育在塑造延续至成年期的认知和社会发展方面起关键作用。","targetForm":"instrumental","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"The new software proved instrumental in shortening the time needed to analyse complex data sets.","translation":"新软件在缩短分析复杂数据集所需时间方面发挥了关键作用。","targetForm":"instrumental","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"International cooperation was instrumental in containing the outbreak before hospitals in the region became overwhelmed.","translation":"国际合作在遏制疫情、避免该地区医院不堪重负方面起到了关键作用。","targetForm":"instrumental","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"The album includes an instrumental track in which the melody is carried by strings rather than by a singer.","translation":"专辑包含一首器乐曲，旋律由弦乐而非歌手承担。","targetForm":"instrumental","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Instrumental monitoring allowed surgeons to observe the patient's vital signs throughout the procedure.","translation":"器械监测让外科医生能够在整个手术过程中观察患者的生命体征。","targetForm":"instrumental","senseId":"source-adj-2","sourceSenseId":"adj-2"}]},"intrigue":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"阴谋"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"激起...的兴趣"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"密谋"}],"examples":[{"sentence":"The political intrigue within the royal court eventually led to the downfall of several powerful ministers.","translation":"宫廷内的政治阴谋最终导致了几位权臣的垮台。","targetForm":"intrigue","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The novel is filled with intrigue and suspense, keeping readers guessing until the very last page.","translation":"这部小说充满了阴谋与悬念，让读者一直猜测到最后一页。","targetForm":"intrigue","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The mysterious origins of ancient artifacts continue to intrigue archaeologists and historians alike.","translation":"古代文物的神秘起源继续引起考古学家和历史学家的兴趣。","targetForm":"intrigue","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"What intrigued the researcher most was the unexpected correlation between the two seemingly unrelated variables.","translation":"最让研究人员感兴趣的是两个看似无关的变量之间意想不到的相关性。","targetForm":"intrigued","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"The ambitious nobleman intrigued against the king, secretly plotting to seize the throne for himself.","translation":"那位野心勃勃的贵族密谋反对国王，暗中策划为自己夺取王位。","targetForm":"intrigued","senseId":"source-v-1","sourceSenseId":"v-1"}]},"inland":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"内陆的"}],"examples":[{"sentence":"Because inland areas are more susceptible to extreme temperature fluctuations, farmers there need to adopt climate-resilient crops.","translation":"由于内陆地区更容易受到极端温度波动的影响，那里的农民需要采用适应气候的作物。","targetForm":"inland","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The government is promoting inland tourism to diversify the economy, rather than relying solely on coastal attractions.","translation":"政府正在推广内陆旅游以实现经济多元化，而不是仅仅依赖沿海景点。","targetForm":"inland","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"While inland waterways offer a cost-effective transport option, their development requires substantial investment in dredging and locks.","translation":"虽然内陆水道提供了一种经济高效的运输选择，但其发展需要对疏浚和船闸进行大量投资。","targetForm":"inland","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Inland cities, which often lack direct access to seaports, must rely on efficient rail and road networks to facilitate trade.","translation":"内陆城市通常缺乏直达海港的通道，必须依赖高效的铁路和公路网络来促进贸易。","targetForm":"inland","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Inland regions, despite their rich natural resources, often struggle with depopulation as young people migrate to coastal cities for better opportunities.","translation":"内陆地区尽管拥有丰富的自然资源，但由于年轻人为了更好的机会迁移到沿海城市，往往面临人口减少的问题。","targetForm":"inland","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"interfere":{"senseGroups":[{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"干涉"}],"examples":[{"sentence":"He has no right to interfere in our family affairs.","translation":"他无权干涉我们的家庭事务。","targetForm":"interfere","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"You have no right to interfere in other people's affairs.","translation":"你没有干涉他人事务的权力。","targetForm":"interfere","senseId":"source-v-3","sourceSenseId":"v-3"}]},"innumerable":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"无数的"}],"examples":[{"sentence":"Although innumerable studies have examined the issue, a consensus remains difficult because the available data conflict.","translation":"尽管无数研究已经考察了该问题，共识仍难形成，因为现有数据彼此冲突。","targetForm":"innumerable","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Innumerable small businesses have adopted digital tools that help them reach customers beyond their local markets.","translation":"无数小企业采用了数字工具，帮助它们触及本地市场之外的顾客。","targetForm":"innumerable","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The museum holds innumerable objects whose careful documentation can reveal how ordinary people lived in earlier periods.","translation":"博物馆收藏无数物件，细致记录它们可以揭示早期普通人的生活方式。","targetForm":"innumerable","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"While the policy prompted innumerable debates, it also led to practical improvements in public health services.","translation":"尽管这项政策引发无数争论，它也带来了公共卫生服务的实际改善。","targetForm":"innumerable","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Innumerable volunteers contributed to the relief effort, without whom the response would have been far less effective.","translation":"无数志愿者参与救援；没有他们，这次响应的效果会差得多。","targetForm":"innumerable","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"inform":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"通知"}],"examples":[{"sentence":"Although the deadline was approaching, the manager failed to inform the team, which led to unnecessary stress.","translation":"尽管截止日期临近，经理却没有通知团队，这导致了不必要的压力。","targetForm":"inform","senseId":"source-v-1","sourceSenseId":"v-1"}]},"invitation":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"请柬"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"邀请"}],"examples":[{"sentence":"There's a photo of the bride and groom together on the invitation sent to friends.","translation":"发给好朋友的请帖上有新郎新娘合影的照片。","targetForm":"invitation","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"As such is the case, I am sorry I can't accept your kind invitation.","translation":"照这样的情况，很抱歉，我不能接受你的盛情邀请。","targetForm":"invitation","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"It is very impolite of her to decline our invitation.","translation":"她拒绝我们的邀请很不礼貌。","targetForm":"invitation","senseId":"source-n-1","sourceSenseId":"n-1"}]},"interior":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"内部"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"内政"},{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"内部的"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"心灵的"},{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"内地的"}],"examples":[{"sentence":"Although the exterior appeared plain, the interior of the library was filled with daylight and carefully restored woodwork.","translation":"尽管外观朴素，图书馆内部却充满自然光，并保留了精心修复的木作。","targetForm":"interior","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The minister of the interior announced new measures after regional officials reported persistent failures in emergency communication.","translation":"地区官员报告应急通信持续失灵后，内政部长宣布了新措施。","targetForm":"interior","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The designers selected durable interior materials because the station would receive thousands of passengers each day.","translation":"设计师选择耐用的室内材料，因为车站每天将接待数千名乘客。","targetForm":"interior","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Her interior doubts remained unspoken, yet they shaped the careful questions she asked during the negotiation.","translation":"她内心的疑虑始终没有说出口，却影响了她在谈判中提出的审慎问题。","targetForm":"interior","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"Improved rail links allowed farmers in interior regions to send perishable goods to coastal markets before they spoiled.","translation":"改善后的铁路连接，使内地农民能在易腐货物变质前将其运往沿海市场。","targetForm":"interior","senseId":"source-adj-3","sourceSenseId":"adj-3"}]},"incredible":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"难以置信的"}],"examples":[{"sentence":"The claim initially sounded incredible, but newly released records confirmed that the archive had been hidden for decades.","translation":"这项说法起初听来难以置信，但新公开的记录证实该档案确实被隐藏了数十年。","targetForm":"incredible","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"With incredible patience, the mediator reframed each accusation until both sides could identify a shared concern.","translation":"调解员以惊人的耐心重新表述每一项指责，直到双方都能找到共同关切。","targetForm":"incredible","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Although the laboratory had limited resources, its researchers made incredible progress by sharing equipment across departments.","translation":"尽管实验室资源有限，研究人员仍通过跨部门共享设备取得了惊人的进展。","targetForm":"incredible","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The bridge's incredible span was achieved through a design that distributed weight across a network of slender cables.","translation":"这座桥惊人的跨度，得益于一种将重量分散到纤细缆索网络中的设计。","targetForm":"incredible","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"It seemed incredible that such a small change in wording could alter how participants understood the entire question.","translation":"如此微小的措辞变化竟能改变参与者对整道题的理解，这似乎难以置信。","targetForm":"incredible","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"install":{"senseGroups":[{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"使就职"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"安装"}],"examples":[{"sentence":"Earlier, in 1995, China installed its own Panchen Lama after its security services abducted the Tibetans’ six-year-old appointee, who has simply disappeared, along with his family.","translation":"在更早之前的1995年，中国国家安全机关在劫持了藏人选定的6岁班禅喇嘛继任人及其全家之后拥立了自己的班禅喇嘛。","targetForm":"installed","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"Since I installed solar panels on my house, my energy bill has been cut in half.","translation":"自从我在我的房子上装了太阳能电池板，我的电费单就减半了。","targetForm":"installed","senseId":"source-v-1","sourceSenseId":"v-1"}]},"infrastructure":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"基础设施"}],"examples":[{"sentence":"Saudi Arabia is boosting its spending on social and infrastructure investments substantially, as well as expanding oil sector capacity.","translation":"沙特阿拉伯将大大增加其在社会和基础设施上投资的力度，并且将扩大石油的产能。","targetForm":"infrastructure","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"This will require infrastructure development, as well as reliable systems for procuring supplies, maintaining equipment, and training and retaining personnel.","translation":"监控严重耐药型结核病的重点包括鼓励进行对二线药物的可靠的敏感性测试，并将相关信息与艾滋病测试信息一起，纳入现有的结核病监控计划之中。","targetForm":"infrastructure","senseId":"source-n-2","sourceSenseId":"n-2"}]},"institute":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"学会"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"开始"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"创立"},{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"任命"}],"examples":[{"sentence":"The institute brought historians and engineers together, because the restoration project required both archival and technical expertise.","translation":"该研究所汇集历史学家和工程师，因为修复项目同时需要档案和技术专长。","targetForm":"institute","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"After consultation with residents, the council instituted a night bus service for districts that had lost their rail link.","translation":"与居民协商后，委员会开始实行夜间公交服务，覆盖失去铁路连接的地区。","targetForm":"instituted","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The charity instituted an annual fellowship so that early-career researchers could complete work that conventional grants rarely support.","translation":"该慈善机构设立了年度研究金，使职业早期研究者能完成传统资助很少支持的工作。","targetForm":"instituted","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The university instituted a new dean after the outgoing leader had completed the handover of major responsibilities.","translation":"原负责人完成主要职责交接后，大学任命了一位新院长。","targetForm":"instituted","senseId":"source-v-4","sourceSenseId":"v-4"},{"sentence":"Although the institute is small, its independent review process gives its recommendations considerable public credibility.","translation":"尽管该机构规模不大，其独立评审流程仍使建议具有相当的公众可信度。","targetForm":"institute","senseId":"source-n-1","sourceSenseId":"n-1"}]},"instrument":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"仪器"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"工具"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"手段"}],"examples":[{"sentence":"The laboratory calibrated each instrument before the trial, because a small error could distort every later measurement.","translation":"实验室在试验前校准每台仪器，因为微小误差可能扭曲后续所有测量。","targetForm":"instrument","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Although the violin is a demanding instrument, regular practice teaches players to listen closely to changes in tone.","translation":"尽管小提琴是一种难掌握的乐器，规律练习会教会演奏者细听音色变化。","targetForm":"instrument","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The questionnaire was a useful instrument for gathering comparable responses, provided that participants understood every question.","translation":"只要参与者理解每个问题，问卷便是收集可比较回答的有效工具。","targetForm":"instrument","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Education can be an instrument of social mobility when institutions remove barriers that prevent capable students from progressing.","translation":"当机构消除阻碍有能力学生进步的障碍时，教育可以成为社会流动的手段。","targetForm":"instrument","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The treaty served as an instrument for cooperation rather than a final settlement, which required years of further negotiation.","translation":"该条约是促进合作的手段，而非最终解决方案，后者还需要多年进一步谈判。","targetForm":"instrument","senseId":"source-n-2","sourceSenseId":"n-2"}]},"indicative":{"senseGroups":[{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"表示...的"},{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"指示的"}],"examples":[{"sentence":"The upward trend is indicative of growing demand, although analysts will need several more quarters of data.","translation":"上升趋势表明需求正在增长，尽管分析师还需要几个季度的数据。","targetForm":"indicative","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"A single late payment is not necessarily indicative of poor management when the organisation has otherwise stable finances.","translation":"如果机构其他财务状况稳定，一次逾期付款不一定表明管理不善。","targetForm":"indicative","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"The colour-coded map is indicative rather than exact, so users should consult local measurements before making decisions.","translation":"这张色彩图是指示性的而非精确数据，因此用户在决定前应查阅本地测量结果。","targetForm":"indicative","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Although the survey was small, the responses were indicative of concerns raised repeatedly in public meetings.","translation":"尽管调查规模很小，回应仍表明了公众会议中反复提出的担忧。","targetForm":"indicative","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"The first reading is indicative of a fault in the sensor, not proof that the whole system has failed.","translation":"第一次读数表明传感器可能存在故障，并不能证明整个系统已经失效。","targetForm":"indicative","senseId":"source-adj-3","sourceSenseId":"adj-3"}]},"insist":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"坚持"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"坚决主张"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"强调"}],"examples":[{"sentence":"The chair insisted on seeing the original figures before approving a summary that might conceal important differences.","translation":"主席坚持查看原始数据后才批准可能掩盖重要差异的摘要。","targetForm":"insisted","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Although several members disagreed, she insisted that the policy had to protect renters as well as property owners.","translation":"尽管几位成员不同意，她仍坚持认为政策必须保护租户和业主。","targetForm":"insisted","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The report insists on the distinction between a temporary delay and a permanent reduction in public funding.","translation":"报告强调必须区分暂时延误与公共资金永久削减。","targetForm":"insists","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"When the contractor attempted to change the terms, residents insisted on a written explanation before accepting any revision.","translation":"承包商试图更改条款时，居民坚持先得到书面解释，再接受任何修改。","targetForm":"insisted","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The author insists that uncertainty should be acknowledged, because false precision can mislead readers more than honest caution.","translation":"作者坚持认为应承认不确定性，因为虚假的精确性比诚实的谨慎更容易误导读者。","targetForm":"insists","senseId":"source-v-2","sourceSenseId":"v-2"}]},"interrupt":{"senseGroups":[{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"插嘴"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"妨碍"}],"examples":[{"sentence":"Beth has a strong habit of interrupting people while they are talking.","translation":"贝丝很喜欢在别人说话的时候插嘴。","targetForm":"interrupting","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"I will try not to interrupt you while you are studying.","translation":"我会尽量不打扰你复习。","targetForm":"interrupt","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Tom didn't want to interrupt Mary while she was studying.","translation":"Tom不想在Mary读书时骚扰她。","targetForm":"interrupt","senseId":"source-v-2","sourceSenseId":"v-2"}]},"index":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"指针"}],"examples":[{"sentence":"The hand has five fingers: the thumb, the index finger, the middle finger, the ring finger, and the pinky.","translation":"人的手有五个手指: 拇指、食指、中指、无名指和小指。","targetForm":"index","senseId":"source-n-2","sourceSenseId":"n-2"}]},"invite":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"邀请"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"请求"},{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"招致"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"邀请"}],"examples":[{"sentence":"The organisers invited local residents to the design meeting, so that the final plan reflected everyday experience as well as expert advice.","translation":"组织者邀请当地居民参加设计会议，使最终方案既反映日常经验，也采纳专家建议。","targetForm":"invited","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The chair invited questions after the presentation, particularly from people whose concerns had not appeared in the written report.","translation":"演示结束后，主席邀请提问，尤其欢迎书面报告未体现其关切的人发言。","targetForm":"invited","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Ignoring repeated warnings can invite serious criticism, because it suggests that preventable risks were treated casually.","translation":"忽视反复警告可能招致严厉批评，因为这意味着可预防的风险被轻率对待。","targetForm":"invite","senseId":"source-v-4","sourceSenseId":"v-4"},{"sentence":"She received an invite to join the panel, although she ultimately declined because the timing conflicted with fieldwork.","translation":"她收到加入评审组的邀请，但最终因时间与田野工作冲突而婉拒。","targetForm":"invite","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The festival will invite submissions from emerging writers whose work engages thoughtfully with the year's central theme.","translation":"该节日将征集新锐作家的投稿，其作品需深入回应年度核心主题。","targetForm":"invite","senseId":"source-v-1","sourceSenseId":"v-1"}]},"income":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"收入"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"收益"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"流入"}],"examples":[{"sentence":"Although her income rose after the promotion, she continued to save cautiously because her work remained dependent on short contracts.","translation":"尽管晋升后收入增加，她仍谨慎储蓄，因为工作仍依赖短期合同。","targetForm":"income","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The report compares household income across districts, where high housing costs can make similar salaries feel very different.","translation":"报告比较了各区家庭收入，而高住房成本会使相似薪资带来截然不同的感受。","targetForm":"income","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Rental income helped the cooperative maintain the historic building, whose repair costs could not be covered by ticket sales alone.","translation":"租金收入帮助合作社维护历史建筑，其维修费用无法只靠门票支付。","targetForm":"income","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The charity recorded an unexpected income from donations after the public campaign, then allocated it to the emergency fund.","translation":"公开活动后，慈善机构记录了一笔意外捐款流入，随后将其划入应急基金。","targetForm":"income","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Policies that protect income during temporary unemployment can prevent families from losing housing after a short disruption.","translation":"在暂时失业期间保护收入的政策，能防止家庭因短期波动失去住房。","targetForm":"income","senseId":"source-n-1","sourceSenseId":"n-1"}]},"intellectual":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"有知识者"}],"examples":[{"sentence":"But this argument’s intellectual foundations – first laid out in a 2002 paper by 13 members of the Fed’s Washington, DC, research staff – are shaky, at best.","translation":"但该理论的思想基础 — — 其根源可以追溯到华盛顿美联储研究团队2002年的一篇论文 — — 大有问题。","targetForm":"intellectual","senseId":"source-n-1","sourceSenseId":"n-1"}]},"inside":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"内部"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"内幕"},{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"内部的"},{"id":"source-adv-1","partOfSpeech":"adv.","sourceSenseIds":["adv-1"],"sense":"在里面"},{"id":"source-prep-1","partOfSpeech":"prep.","sourceSenseIds":["prep-1"],"sense":"在...之内"}],"examples":[{"sentence":"Although the house looked narrow from the street, the inside had been redesigned to create a bright shared workspace.","translation":"尽管房子从街上看很狭窄，内部已重新设计成明亮的共享工作空间。","targetForm":"inside","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The journalist had no inside information, so she distinguished carefully between verified facts and rumours circulating online.","translation":"记者没有内幕消息，因此谨慎区分已核实事实与网上流传的传闻。","targetForm":"inside","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The inside team reviewed the proposal before it was shared publicly, which allowed technical errors to be corrected early.","translation":"内部团队在公开分享前审查了提案，使技术错误能及早更正。","targetForm":"inside","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"When the rain became heavier, the guide asked visitors to come inside until the exposed path was safe again.","translation":"雨势变大时，导游请访客进到里面，直到暴露的小路再次安全。","targetForm":"inside","senseId":"source-adv-1","sourceSenseId":"adv-1"},{"sentence":"The response must arrive inside two weeks, otherwise the committee cannot include it in the scheduled review.","translation":"回复必须在两周之内到达，否则委员会无法将其纳入预定审查。","targetForm":"inside","senseId":"source-prep-1","sourceSenseId":"prep-1"}]},"intermediate":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"中间物"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"中级"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"调停者"}],"examples":[{"sentence":"The intermediate phase of the project requires careful coordination between departments to ensure that deadlines are met.","translation":"项目的中间阶段需要各部门之间仔细协调，以确保按时完成。","targetForm":"intermediate","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the course is designed for intermediate learners, it also provides foundational review for those who need it.","translation":"尽管该课程是为中级学习者设计的，但它也为需要的人提供基础复习。","targetForm":"intermediate","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Because the software serves as an intermediate between different operating systems, it enables seamless data transfer.","translation":"由于该软件充当不同操作系统之间的中间件，它实现了无缝数据传输。","targetForm":"intermediate","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"When an intermediate product is contaminated, the entire manufacturing batch must be discarded to ensure safety.","translation":"当中间产品受到污染时，必须丢弃整个生产批次以确保安全。","targetForm":"intermediate","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Students who reach an intermediate level of proficiency often struggle with idiomatic expressions, which are rarely taught in textbooks.","translation":"达到中级水平的学生常常在惯用表达上遇到困难，而这些在教科书中很少教授。","targetForm":"intermediate","senseId":"source-n-3","sourceSenseId":"n-3"}]},"inevitable":{"senseGroups":[{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"必然的"}],"examples":[{"sentence":"So, while this latest bear-market rally may continue for a bit longer, renewed downward pressure on stocks and other risky assets is inevitable.","translation":"因此，尽管最近这次熊市反弹将持续更长时间，但股票和其他风险性资产必将重新感受到向下的压力。","targetForm":"inevitable","senseId":"source-adj-2","sourceSenseId":"adj-2"}]},"integrity":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"正直"}],"examples":[{"sentence":"Although the pressure to succeed was immense, she maintained her integrity by refusing to cheat on the exam.","translation":"尽管成功的压力巨大，她仍通过拒绝在考试中作弊来保持自己的正直。","targetForm":"integrity","senseId":"source-n-1","sourceSenseId":"n-1"}]},"interview":{"senseGroups":[{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"面试"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"访问"}],"examples":[{"sentence":"Although she was nervous during the interview, her thorough preparation allowed her to answer each question confidently.","translation":"尽管她在面试时很紧张，但充分的准备使她能够自信地回答每个问题。","targetForm":"interview","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"The journalist secured an exclusive interview with the prime minister, thereby gaining insight into the new policy.","translation":"记者获得了对首相的独家采访，从而深入了解了新政策。","targetForm":"interview","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The interview, which was conducted by a panel of experts, focused on the candidate's problem-solving abilities.","translation":"由专家小组进行的面试，重点考察了候选人的解决问题能力。","targetForm":"interview","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"Because the interview was rescheduled twice, the applicant began to doubt the company's professionalism.","translation":"由于面试被重新安排了两次，申请人开始怀疑公司的专业性。","targetForm":"interview","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"A successful interview requires not only strong qualifications but also effective communication skills.","translation":"成功的面试不仅需要强大的资历，还需要有效的沟通技巧。","targetForm":"interview","senseId":"source-n-4","sourceSenseId":"n-4"}]},"inspire":{"senseGroups":[{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"启示"},{"id":"source-v-5","partOfSpeech":"v.","sourceSenseIds":["v-5"],"sense":"鼓舞"},{"id":"source-v-8","partOfSpeech":"v.","sourceSenseIds":["v-8"],"sense":"赋予灵感"},{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"吸入"}],"examples":[{"sentence":"The archive inspired the students to ask better questions about whose voices were missing from the official record.","translation":"档案启发学生提出更好的问题：官方记录中缺少了谁的声音。","targetForm":"inspired","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"Although the first attempt failed, the team's persistence inspired others to contribute ideas instead of withdrawing.","translation":"尽管第一次尝试失败，团队的坚持仍鼓舞其他人贡献想法，而不是退出。","targetForm":"inspired","senseId":"source-v-5","sourceSenseId":"v-5"},{"sentence":"A clear example can inspire a reader to test an abstract principle in a new context.","translation":"清晰的例子能启发读者在新语境中检验抽象原则。","targetForm":"inspire","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"The building's simple forms inspired the architect, who adapted them for a library with much wider access.","translation":"建筑简洁的形态给了建筑师灵感，他将其改造用于一座更易进入的图书馆。","targetForm":"inspired","senseId":"source-v-8","sourceSenseId":"v-8"},{"sentence":"During the science demonstration, pupils watched how air is inspired and released as part of normal breathing.","translation":"在科学演示中，学生观察空气如何作为正常呼吸的一部分被吸入和呼出。","targetForm":"inspired","senseId":"source-v-4","sourceSenseId":"v-4"}]},"intelligence":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"智力"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"情报"}],"examples":[{"sentence":"Corporations and the military depend on assessment and sorting devices that are little more than disguised intelligence tests.","translation":"也许必须对智力给予一些关注，然而忽略起码是同样重要的认知能力—这一趋势却不合理：正是这种能力支撑起理性的思维和行为。","targetForm":"intelligence","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"That much was understood widely by entrenched Arab dictators, who saw to it that their intelligence and security corps extinguished any flame before it could spread.","translation":"照理说那些老谋深算的独裁者们对此也早有准备，他们靡下的情报安全机构也时刻准备着扑灭任何示威苗头。","targetForm":"intelligence","senseId":"source-n-2","sourceSenseId":"n-2"}]},"integrate":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"综合"},{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"成一体"},{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"完整的"}],"examples":[{"sentence":"The course integrates theory with practical tasks that students can complete independently.","translation":"这门课程将理论与学生可独立完成的实践任务结合起来。","targetForm":"integrates","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"New members integrated quickly after the team agreed on clear ways to share information.","translation":"团队确定清晰的信息共享方式后，新成员很快融入其中。","targetForm":"integrated","senseId":"source-v-4","sourceSenseId":"v-4"},{"sentence":"The software can integrate data from different sources without losing important details.","translation":"该软件能整合不同来源的数据，而不丢失重要细节。","targetForm":"integrate","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"An integrated system allows the library to manage loans, records, and notices together.","translation":"一套整合系统使图书馆能够统一管理借阅、记录和通知。","targetForm":"integrated","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The integrated design prevented small changes in one section from disrupting the entire process.","translation":"整合式设计避免一处小改动扰乱整个流程。","targetForm":"integrated","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"inferior":{"senseGroups":[{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"较差的"},{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"次等的"}],"examples":[{"sentence":"Everyone who has had to deal with AI customer service knows how inferior it is to actual humans.","translation":"每个曾经与 AI 客服打交道的人都知道，AI 与真人相比有多么逊色。","targetForm":"inferior","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"You cannot compare the strength of a man to that of a tiger, but nevertheless, the tiger is still the inferior creature.","translation":"虎与人是无法比拼力量的，但是，老虎还是比人类低等。","targetForm":"inferior","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"There is no reason for you to feel inferior to anyone.","translation":"你没理由觉得自己比别人差的。","targetForm":"inferior","senseId":"source-adj-2","sourceSenseId":"adj-2"}]},"interface":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"分界面"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"接触面"},{"id":"source-other-1","partOfSpeech":"计算机","sourceSenseIds":["other-1"],"sense":"接口","contextReviewed":true},{"id":"source-other-2","partOfSpeech":"计算机","sourceSenseIds":["other-2"],"sense":"用户界面","contextReviewed":true}],"examples":[{"sentence":"The interface between the research team and the community was strengthened by monthly meetings and shared reports.","translation":"研究团队与社区之间的联系界面通过每月会议和共享报告得到加强。","targetForm":"interface","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"At the interface between the two materials, engineers found a thin layer that affected the product's durability.","translation":"在两种材料的接触面上，工程师发现了一层会影响产品耐用性的薄层。","targetForm":"interface","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The payment interface allows the website to exchange verified information with several banks securely.","translation":"该支付接口使网站能够与多家银行安全交换经验证的信息。","targetForm":"interface","senseId":"source-other-1","sourceSenseId":"other-1"},{"sentence":"Because the interface was documented clearly, another team could connect its software without rewriting the entire system.","translation":"由于接口文档写得清楚，另一个团队无需重写整个系统就能连接其软件。","targetForm":"interface","senseId":"source-other-1","sourceSenseId":"other-1"},{"sentence":"Although the application had powerful features, its interface confused new users who could not find the main controls.","translation":"尽管该应用功能强大，它的用户界面仍让找不到主要控件的新用户感到困惑。","targetForm":"interface","senseId":"source-other-2","sourceSenseId":"other-2"}]},"intuition":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"直觉"}],"examples":[{"sentence":"While data analysis is essential for decision-making, intuition can guide researchers toward promising hypotheses that algorithms might overlook.","translation":"虽然数据分析对决策至关重要，但直觉可以引导研究人员找到算法可能忽视的有前景的假设。","targetForm":"intuition","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although intuition can sometimes lead to biased judgments, it remains a valuable cognitive tool when combined with critical reflection.","translation":"尽管直觉有时会导致有偏见的判断，但当与批判性反思相结合时，它仍然是一种宝贵的认知工具。","targetForm":"intuition","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Experienced teachers often rely on intuition to sense when a student is struggling, even before test results confirm it.","translation":"经验丰富的教师常常依靠直觉来察觉学生何时遇到困难，甚至在考试成绩证实之前就能感觉到。","targetForm":"intuition","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Her intuition told her that the proposal, though superficially attractive, contained hidden risks.","translation":"她的直觉告诉她，这项提议虽然表面上很有吸引力，但隐藏着风险。","targetForm":"intuition","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because his intuition about market trends had proved accurate in the past, the manager decided to trust his gut feeling once more.","translation":"由于他过去对市场趋势的直觉被证明是准确的，经理决定再次相信自己的直觉。","targetForm":"intuition","senseId":"source-n-1","sourceSenseId":"n-1"}]},"intense":{"senseGroups":[{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"紧张的"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"强烈的"}],"examples":[{"sentence":"Because the debate touched on deeply held beliefs, the atmosphere in the lecture hall grew increasingly intense.","translation":"由于辩论触及了根深蒂固的信念，报告厅里的气氛变得越来越紧张。","targetForm":"intense","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"Despite the intense heat, the volunteers continued to plant trees in the deforested area, demonstrating remarkable dedication.","translation":"尽管酷热难耐，志愿者们仍继续在砍伐区植树，展现了非凡的奉献精神。","targetForm":"intense","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"An intense focus on renewable energy is essential if we are to mitigate the effects of climate change.","translation":"如果我们要减轻气候变化的影响，对可再生能源的高度关注是必不可少的。","targetForm":"intense","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"The intense competition for limited graduate school placements forces applicants to distinguish themselves through research experience.","translation":"研究生院有限名额的激烈竞争迫使申请者通过研究经历来脱颖而出。","targetForm":"intense","senseId":"source-adj-3","sourceSenseId":"adj-3"}]},"inn":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"客栈"}],"examples":[{"sentence":"Although the inn had only six rooms, its owner remembered every returning guest and their preferred breakfast.","translation":"尽管这家小旅馆只有六间客房，老板仍记得每位回头客及其喜欢的早餐。","targetForm":"inn","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The hikers chose an inn near the trailhead so that they could begin the climb before sunrise.","translation":"徒步者选择了步道起点附近的一家客栈，以便在日出前开始攀登。","targetForm":"inn","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"During the festival, the old inn became a meeting place for musicians who travelled from nearby villages.","translation":"节日期间，这家老客栈成了从附近村庄赶来的音乐家的聚会场所。","targetForm":"inn","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Before booking the inn, the family checked whether it offered a late arrival service for the evening train.","translation":"预订客栈前，这家人查看它是否为晚间火车到达的客人提供延迟入住服务。","targetForm":"inn","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The inn's dining room overlooked the river, which made even a simple meal feel like part of the journey.","translation":"这家客栈的餐厅俯瞰河流，使即使简单的一餐也仿佛成为旅程的一部分。","targetForm":"inn","senseId":"source-n-2","sourceSenseId":"n-2"}]},"intrude":{"senseGroups":[{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"侵入"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"闯入"}],"examples":[{"sentence":"Governments must ensure that surveillance measures do not intrude on citizens' legitimate expectations of privacy.","translation":"政府必须确保监控措施不侵犯公民对隐私的合理期望。","targetForm":"intrude","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Although the new regulation aims to protect consumers, it may intrude upon individual autonomy.","translation":"尽管新规旨在保护消费者，但它可能侵犯个人自主权。","targetForm":"intrude","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Because constant notifications intrude into focused work, many professionals disable them during deep tasks.","translation":"由于持续的通知会干扰专注工作，许多专业人士在进行深度任务时会将其关闭。","targetForm":"intrude","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The court ruled that the company's data collection practices intrude upon fundamental rights.","translation":"法院裁定该公司的数据收集行为侵犯了基本权利。","targetForm":"intrude","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"When journalists intrude into private grief, they often cause lasting emotional harm.","translation":"当记者闯入私人悲痛时，他们往往会造成持久的情感伤害。","targetForm":"intrude","senseId":"source-v-1","sourceSenseId":"v-1"}]},"inhabit":{"senseGroups":[{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"栖息"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"占据"}],"examples":[{"sentence":"Because the cave system remains largely unexplored, scientists believe that unknown organisms may inhabit its deepest chambers.","translation":"由于该洞穴系统大部分尚未探索，科学家认为未知生物可能栖息在其最深的洞室中。","targetForm":"inhabit","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"While urban expansion threatens natural habitats, many bird species continue to inhabit city parks and green spaces.","translation":"虽然城市扩张威胁着自然栖息地，许多鸟类仍继续栖息在城市公园和绿地中。","targetForm":"inhabit","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"Although the region is known for its extreme temperatures, several resilient species inhabit its arid plains.","translation":"尽管该地区以极端气温着称，仍有几种适应力强的物种栖息在其干旱的平原上。","targetForm":"inhabit","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"The cultural values that inhabit a society often shape its legal framework, thereby influencing individual behavior.","translation":"一个社会所蕴含的文化价值观往往塑造其法律框架，从而影响个人行为。","targetForm":"inhabit","senseId":"source-v-2","sourceSenseId":"v-2"}]},"into":{"senseGroups":[{"id":"source-prep-4","partOfSpeech":"prep.","sourceSenseIds":["prep-4"],"sense":"成为...状况"}],"examples":[{"sentence":"I believe that it was not, and that two important factors have come into play in the last two years.","translation":"我认为答案是否定的，在过去两年中出现了两个重要因素。","targetForm":"into","senseId":"source-prep-4","sourceSenseId":"prep-4"}]},"in":{"senseGroups":[{"id":"source-prep-3","partOfSpeech":"prep.","sourceSenseIds":["prep-3"],"sense":"处于...之中"},{"id":"source-prep-2","partOfSpeech":"prep.","sourceSenseIds":["prep-2"],"sense":"在...之内"}],"examples":[{"sentence":"Against that backdrop, one can assess current growth patterns in the global economy and its various parts.","translation":"在上述背景下，我们可以对全球经济目前的增长模式及其组成部分进行评估。","targetForm":"in","senseId":"source-prep-3","sourceSenseId":"prep-3"},{"sentence":"In Israel, Obama will encounter a country that has indeed moved, but not toward a missing center.","translation":"奥巴马所面临的问题是以色列正沿着自身的轨道运行，并且离中间路线越来越远。","targetForm":"in","senseId":"source-prep-2","sourceSenseId":"prep-2"}]},"inner":{"senseGroups":[{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"内心的"}],"examples":[{"sentence":"Music is inner life, and he will never suffer loneliness who has inner life.","translation":"音乐是内心世界，拥有了内心世界的他永远不会觉得孤独。","targetForm":"inner","senseId":"source-adj-2","sourceSenseId":"adj-2"}]},"increasingly":{"senseGroups":[{"id":"source-adv-1","partOfSpeech":"adv.","sourceSenseIds":["adv-1"],"sense":"逐渐地"}],"examples":[{"sentence":"The fact that world leaders now increasingly talk about this imperative suggests that the lesson of Chernobyl is finally being understood.","translation":"世界领导人们加大谈论这一迫切问题这一事实就表明世界终于开始理解切尔诺贝利的教训。","targetForm":"increasingly","senseId":"source-adv-1","sourceSenseId":"adv-1"}]},"instead":{"senseGroups":[{"id":"source-adv-2","partOfSpeech":"adv.","sourceSenseIds":["adv-2"],"sense":"反而"}],"examples":[{"sentence":"Instead of going hungry, humans around the world on a per capita basis are eating more calories than ever before.","translation":"世界各国人口非但没有挨饿，人均摄入的卡路里数量反而比以往任何时候都多。","targetForm":"instead","senseId":"source-adv-2","sourceSenseId":"adv-2"}]},"introduce":{"senseGroups":[{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"引入"}],"examples":[{"sentence":"Of these, Taoism is a native religion, the others having been introduced from foreign lands.","translation":"其中，道教是本国的，其他是从国外引进的。","targetForm":"introduced","senseId":"source-v-2","sourceSenseId":"v-2"}]},"instinct":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"直觉"}],"examples":[{"sentence":"Two people who have never run a presidential campaign, and whose political instincts contradict each other’s, are now running Trump’s operation.","translation":"两个从未管理过总统竞选、且政治直觉相互矛盾的人正在管理特朗普的总统选举。","targetForm":"instincts","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"To be a good batter, you've got to hang loose and follow your instincts.","translation":"想成为一个好的击球手的话，你要在球场上时刻保持镇定，还要学会相信自己的直觉。","targetForm":"instincts","senseId":"source-n-2","sourceSenseId":"n-2"}]},"independence":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"独立"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"自立"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"自主"}],"examples":[{"sentence":"Financial independence allowed her to choose work that matched her long-term values.","translation":"经济独立使她能选择符合长期价值观的工作。","targetForm":"independence","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The course encourages independence by asking students to evaluate sources for themselves.","translation":"这门课程要求学生自行评估资料来源，从而培养独立性。","targetForm":"independence","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Young adults often gain confidence as they develop greater independence in daily life.","translation":"年轻人在日常生活中获得更大自主性时，往往会更有信心。","targetForm":"independence","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The researcher defended the independence of the review process from commercial pressure.","translation":"研究人员捍卫评审过程不受商业压力影响的独立性。","targetForm":"independence","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Learning to travel alone can be a useful step toward practical independence.","translation":"学会独自出行可以是迈向实际自立的有益一步。","targetForm":"independence","senseId":"source-n-2","sourceSenseId":"n-2"}]},"interference":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"干涉"}],"examples":[{"sentence":"Saudi Arabia has two large concerns about the Islamic Republic: its quest for nuclear weapons and its interference in its neighbors’ affairs.","translation":"沙特阿拉伯对伊朗有两大担忧：其对核武器的诉求以及其对邻国事务的干预。","targetForm":"interference","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"I won't allow you to continue your interference in my daughter's life.","translation":"我不允许你继续干涉我女儿的生活。","targetForm":"interference","senseId":"source-n-2","sourceSenseId":"n-2"}]},"institution":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"机构"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"制度"}],"examples":[{"sentence":"First, we will continue to support the institutions that helped get us to where we are now.","translation":"首先，我们将继续支持对实现当前目标做出贡献的机构。","targetForm":"institutions","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The question now is whether Western institutions are strong enough to contain the global plutocracy that low interest rates have wrought.","translation":"现在的问题是西方制度是否足够强大，能够遏制低利率所造就的全球财阀。","targetForm":"institutions","senseId":"source-n-3","sourceSenseId":"n-3"}]},"influential":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"有影响的"}],"examples":[{"sentence":"Rousseau was mad but influential; Hume was sane but had no followers.","translation":"卢梭是疯狂的, 但有影响力; 休谟是理智的, 但没有追随者。","targetForm":"influential","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"indispensable":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"不可缺少之物"}],"examples":[{"sentence":"It is for this indispensable quality of statesmanship, not only for having helped bring about German reunification, that Kohl deserves to be remembered and mourned.","translation":"正是这种不可或缺的政治家的品质，而不仅仅是因为带来了德国的重新统一，让科尔值得被铭记和哀悼。","targetForm":"indispensable","senseId":"source-n-1","sourceSenseId":"n-1"}]},"inspiration":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"灵感"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"鼓舞人心的人或物"}],"examples":[{"sentence":"After climbing Mt Fuji I got the inspiration for a poem.","translation":"攀登富士山后，我得到了一首诗的灵感。","targetForm":"inspiration","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"My mother was an angel and an inspiration to me.","translation":"我的母亲是一位天使，也是我的灵感来源。","targetForm":"inspiration","senseId":"source-n-2","sourceSenseId":"n-2"}]},"inverse":{"senseGroups":[{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"相反的"}],"examples":[{"sentence":"The inverse of a non-square matrix is a dangerous thing.","translation":"非方矩阵的逆阵是一个危险的东西。","targetForm":"inverse","senseId":"source-adj-2","sourceSenseId":"adj-2"}]},"involve":{"senseGroups":[{"id":"source-v-6","partOfSpeech":"v.","sourceSenseIds":["v-6"],"sense":"包括；牵涉；使参与","contextReviewed":true},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"包括"}],"examples":[{"sentence":"The project involves students from several departments who bring different practical skills.","translation":"该项目涉及多个系的学生，他们带来不同实践技能。","targetForm":"involves","senseId":"source-v-6","sourceSenseId":"v-6"},{"sentence":"Writing a strong report involves selecting evidence as well as explaining its relevance.","translation":"撰写有力报告既涉及选择证据，也涉及说明其相关性。","targetForm":"involves","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"She became involved in the campaign after seeing how the cuts affected local services.","translation":"看到削减如何影响当地服务后，她参与了这场活动。","targetForm":"involved","senseId":"source-v-6","sourceSenseId":"v-6"},{"sentence":"The investigation involved no private information that was unrelated to the complaint.","translation":"调查未涉及与投诉无关的私人信息。","targetForm":"involved","senseId":"source-v-6","sourceSenseId":"v-6"},{"sentence":"Parents were involved in planning the event, which made the final programme more practical.","translation":"家长参与活动筹备，使最终方案更切合实际。","targetForm":"involved","senseId":"source-v-6","sourceSenseId":"v-6"}]},"interest":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"利息"},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"利益"}],"examples":[{"sentence":"The question now is whether Western institutions are strong enough to contain the global plutocracy that low interest rates have wrought.","translation":"现在的问题是西方制度是否足够强大，能够遏制低利率所造就的全球财阀。","targetForm":"interest","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Public policy that discriminates against and discourages vital innovations in food production is not policy that has the public’s interest at heart.","translation":"由此可见，那些敌视并压制在食品生产方面的重要革新的公共政策并不是真心维护民众利益的政策。","targetForm":"interest","senseId":"source-n-4","sourceSenseId":"n-4"}]},"initial":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"字首"}],"examples":[{"sentence":"Moreover, while global imbalances were immediately reduced in the course of the initial crisis, with the US adjusting its deficit relatively rapidly, they are now re-emerging.","translation":"此外，尽管全球收支失衡在危机爆发之初有所收缩，但随着美国相对快速地调整其赤字，失衡情形又重新出现了。","targetForm":"initial","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Your initial order is subject to a special discount of 5%.","translation":"首次订购可获九五折的特别优惠。","targetForm":"initial","senseId":"source-n-1","sourceSenseId":"n-1"}]},"inch":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"英寸"}],"examples":[{"sentence":"He was beaten to within an inch of his life.","translation":"他被殴打得快死。","targetForm":"inch","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The weather report says we'll get three inches of snow.","translation":"天气预报说会下三英寸雪。","targetForm":"inches","senseId":"source-n-1","sourceSenseId":"n-1"}]},"influence":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"影响力"}],"examples":[{"sentence":"Islamic fundamentalists reckon that what the rest of us regard as the liberalizing influence of technological progress and globalization is a brash re-run of Western colonialism.","translation":"以色列原教旨主义者认为我们其他人眼中技术进步和全球化的自由化影响反应出西方殖民主义不可一世的重新抬头。","targetForm":"influence","senseId":"source-n-1","sourceSenseId":"n-1"}]},"interpret":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"解释"},{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"理解"}],"examples":[{"sentence":"This moment will nap, you will have a dream; But this moment study,you will interpret a dream.","translation":"此刻打盹，你将做梦；而此刻学习，你将圆梦。","targetForm":"interpret","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The same sign may be interpreted differently by different people or different cultures.","translation":"同一个符号，不同的人或不同的文化可能会有不同的解读。","targetForm":"interpreted","senseId":"source-v-4","sourceSenseId":"v-4"}]},"internal":{"senseGroups":[{"id":"source-adj-4","partOfSpeech":"adj.","sourceSenseIds":["adj-4"],"sense":"内部的","contextReviewed":true}],"examples":[{"sentence":"The sense of inevitability could be dispelled by recent shifts in the internal politics of both the Conservative government and the Labour opposition.","translation":"不可避免感可能因为最近在保守党政府和工党反对派内部政治局面的改变而消失。","targetForm":"internal","senseId":"source-adj-4","sourceSenseId":"adj-4"}]},"information":{"senseGroups":[{"id":"source-n-5","partOfSpeech":"n.","sourceSenseIds":["n-5"],"sense":"信息"}],"examples":[{"sentence":"But there is one sector of our lives where adoption of information technology has lagged conspicuously: health care.","translation":"但生活中有一个方面采取信息技术的步伐大大地落后了，这就是医疗卫生。","targetForm":"information","senseId":"source-n-5","sourceSenseId":"n-5"},{"sentence":"And, third, laws intended to protect private information should be reevaluated to ensure that IT companies are unable to profit from exploiting and manipulating it.","translation":"最重要的是，公众必须更加深刻地理解IT的经济效应，特别是改善了如此多的人的生活的技术如何只让如此少的人致富。","targetForm":"information","senseId":"source-n-5","sourceSenseId":"n-5"}]},"interact":{"senseGroups":[{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"交互作用"}],"examples":[{"sentence":"You should interact with the local culture more, to better understand some traditions.","translation":"你应该多接触本文化，多了解一些传统习俗。","targetForm":"interact","senseId":"source-v-2","sourceSenseId":"v-2"}]},"introduction":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"介绍"}],"examples":[{"sentence":"Mr Gilmore is so well known as to need no introduction.","translation":"Gilmore先生如此有名，就不必介绍了。","targetForm":"introduction","senseId":"source-n-1","sourceSenseId":"n-1"}]},"insight":{"senseGroups":[{"id":"source-n-5","partOfSpeech":"n.","sourceSenseIds":["n-5"],"sense":"洞察","contextReviewed":true},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"见识"}],"examples":[{"sentence":"One hopes that what emerges from the parties’ nominating processes is insight into how the successful candidates answer three big questions.","translation":"人们希望从两党提名程序中脱颖而出的是能深刻理解成功候选人如何回答这三大问题。","targetForm":"insight","senseId":"source-n-5","sourceSenseId":"n-5"},{"sentence":"This novel view of human nature and society generates some important insights.","translation":"这种对人性和社会的新看法提供了某些重要线索。","targetForm":"insights","senseId":"source-n-3","sourceSenseId":"n-3"}]},"interval":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"间隔"}],"examples":[{"sentence":"It's best to go to the dentist at regular intervals.","translation":"最好定期去看牙医。","targetForm":"intervals","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The Olympic Games take place at intervals of four years.","translation":"每隔四年，奥运会举行一次。","targetForm":"intervals","senseId":"source-n-1","sourceSenseId":"n-1"}]},"industry":{"senseGroups":[{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"产业"}],"examples":[{"sentence":"The main problem is that these examples are peculiar to the software industry, which provides a woefully insufficient blueprint for the rest of the economy.","translation":"主要的问题在于这些例子都是软件行业的个例，对经济中的其他部分来说远不能成为成功蓝图。","targetForm":"industry","senseId":"source-n-4","sourceSenseId":"n-4"}]},"ink":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"墨水"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"墨汁"}],"examples":[{"sentence":"He gave me a pen whose ink was almost all used up.","translation":"他给了我一支快没水了的笔。","targetForm":"ink","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"India ink produces an interesting pattern when used as a dye.","translation":"墨汁用作染料时会产生有趣的图案。","targetForm":"ink","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"I don't care what color ink, just bring me a pen.","translation":"颜色无所谓，给我一支笔就行了。","targetForm":"ink","senseId":"source-n-1","sourceSenseId":"n-1"}]},"indicate":{"senseGroups":[{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"象征"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"显示"},{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"指出"}],"examples":[{"sentence":"They express disagreement by shaking their heads, which may indicate agreement in other countries.","translation":"他们以摇头表示不同意，而其他国家的人可能以摇头表示同意。","targetForm":"indicate","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"An increase in customer complaints may indicate that business is declining.","translation":"顾客投诉量增加，可能代表生意正在走下坡。","targetForm":"indicate","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"I took his not coming to indicate that he wasn't interested.","translation":"我将他的缺席视为没有兴趣。","targetForm":"indicate","senseId":"source-v-4","sourceSenseId":"v-4"}]},"initiate":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"开始"}],"examples":[{"sentence":"With Russia ostensibly on board, it is up to the US to initiate a transformation in the nuclear-negotiation framework – and that means convincing China to participate.","translation":"因为俄罗斯表面上愿意配合，需要由美国启动核谈判框架的转型工作 — — 这意味着要说服中国参与到谈判过程中。","targetForm":"initiate","senseId":"source-n-2","sourceSenseId":"n-2"}]},"incident":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"事件"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"事变"}],"examples":[{"sentence":"After the incident I came to have a higher opinion of him.","translation":"这个事件过后我对他的评价很高。","targetForm":"incident","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"This incident has made a great impact on the progress of the project.","translation":"这个事件极大影响了项目进度。","targetForm":"incident","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Russia expresses regret for those lost in the hostage incident.","translation":"俄罗斯对在人质事件中牺牲的人们表示哀悼。","targetForm":"incident","senseId":"source-n-2","sourceSenseId":"n-2"}]},"insure":{"senseGroups":[{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"投保"}],"examples":[{"sentence":"It's a crying shame that they weren't insured against fire.","translation":"这简直是太可惜了，他们没有买火险。","targetForm":"insured","senseId":"source-v-3","sourceSenseId":"v-3"}]},"invade":{"senseGroups":[{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"侵略"}],"examples":[{"sentence":"People shouldn't be allowed to invade countries whose names they can't pronounce correctly.","translation":"人们不应该侵犯自己读不正确名字的国家。","targetForm":"invade","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"All oil-rich countries should be invaded and annihilated by US forces to protect their civilian populations and teach them democracy.","translation":"所有石油资源丰富的国家都应该被美国军队入侵并摧毁，以保护那里的平民并向他们传授民主。","targetForm":"invaded","senseId":"source-v-3","sourceSenseId":"v-3"}]},"infinite":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"无限"}],"examples":[{"sentence":"Godwin's law teaches us that any infinite discussion about an arbitrary subject converges to a Nazi comparison.","translation":"高德温法则告诉我们对任何主题的所有无休止的讨论会趋于和纳粹主义的类比。","targetForm":"infinite","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Only two things are infinite, the universe and human stupidity, and I'm not sure about the former.","translation":"世界上只有两个东西是无限的，一为宇宙，一为人类的愚蠢，我所不能肯定的乃是前者。","targetForm":"infinite","senseId":"source-n-1","sourceSenseId":"n-1"}]},"infant":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"婴儿"}],"examples":[{"sentence":"Not far away, screened by the forest, crouched Shiegra, the lioness, intent upon devouring the infant for her evening meal.","translation":"不远处，母狮谢格拉匍匐着，隐匿于林间，正伺机将婴儿吞食，作为她的晚餐。","targetForm":"infant","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"It can make some people, especially the elderly and infants, very ill.","translation":"它可以使一些人，尤其是老人和婴幼儿，病得很重。","targetForm":"infants","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The young woman was carrying an infant in her arms.","translation":"那个年轻女人手抱着婴儿。","targetForm":"infant","senseId":"source-n-1","sourceSenseId":"n-1"}]},"incentive":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"动机"}],"examples":[{"sentence":"However, such incentives do not address the problem of low-quality education, and research shows that the benefits do not always outweigh the costs.","translation":"然而，这种激励措施并没有解决教育质量低的问题，并且研究表明其利益并不总是超出成本。","targetForm":"incentives","senseId":"source-n-1","sourceSenseId":"n-1"}]},"invention":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"发明"}],"examples":[{"sentence":"The result of the invention of the steam engine was that human power was replaced by mechanical power.","translation":"机械力代替人力, 这是蒸汽机发明的结果。","targetForm":"invention","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The invention of TV caused a drastic change in our daily life.","translation":"电视的发明为我们的生活模式带来了巨大的变化。","targetForm":"invention","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Language is one of the most important inventions of mankind.","translation":"语言是人类最重大的发明之一。","targetForm":"inventions","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"This invention was the result of years of patient experiment.","translation":"这发明是多年来耐心实验的成果。","targetForm":"invention","senseId":"source-n-1","sourceSenseId":"n-1"}]},"injure":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"伤害"}],"examples":[{"sentence":"Much of what has happened was predictable, as well over 1,400 men, women, and children have died and more than 4,000 have been injured.","translation":"超过1400名男子、妇女和儿童丧失，另有四千多人受伤，而大部分事情都是在预料之中的。","targetForm":"injured","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"I am very much surprised to hear that he got badly injured in a motorcar accident.","translation":"他因车祸受了重伤的消息让我震惊万分。","targetForm":"injured","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"His wife is in the hospital because she was injured in a car crash.","translation":"他的妻子在医院里因为她在一场车祸中受伤了。","targetForm":"injured","senseId":"source-v-1","sourceSenseId":"v-1"}]},"inquiry":{"senseGroups":[{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"询盘"}],"examples":[{"sentence":"For media inquiries, please contact your local communications or marketing representative.","translation":"如需媒体联络，请与当地客服中心或行销团队联系。","targetForm":"inquiries","senseId":"source-n-4","sourceSenseId":"n-4"}]},"intelligent":{"senseGroups":[{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"智能的"},{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"聪明的"}],"examples":[{"sentence":"It was once thought that there was intelligent life on Mars.","translation":"以前有人以为火星上有智能生物。","targetForm":"intelligent","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"The fundamental cause of the trouble is that in the modern world the stupid are cocksure while the intelligent are full of doubt.","translation":"问题的根源是，在当今世界，愚人充满了自信，而智者充满了怀疑。","targetForm":"intelligent","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Even if an intelligent man loves a woman deeply, he will never show his love to her, but merely keep it in his heart.","translation":"聪明的男人就算爱极了一个女人，也只是藏在心里，绝不会将他的爱在她面前表现出来。","targetForm":"intelligent","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"integral":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"整体"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"积分"}],"examples":[{"sentence":"Nonetheless, the EU and its institutions remain integral to efforts to respond to challenges that require a united front – challenges like those that Europe faces today.","translation":"尽管如此，欧盟及其机构依然在需要一个统一战线去应对挑战时不可或缺的存在 — — 正如那些欧洲目前所面临的挑战。","targetForm":"integral","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The integral and the antiderivative are defined in two different ways, and the Fundamental Theorem of Calculus states the relationship between them.","translation":"积分与反导函数是以两种不同的方式定义的，而微积分基本定理阐述了两者之间的关系。","targetForm":"integral","senseId":"source-n-2","sourceSenseId":"n-2"}]},"innocent":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"无罪的"}],"examples":[{"sentence":"Then, when he asked who had broken the window, all the boys acted innocent.","translation":"当他问起是谁打破了窗户时，所有的男生都显得很无辜。","targetForm":"innocent","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"I keep saying that I'm innocent, but no one will listen.","translation":"我再三申明无罪，但是没人听我讲。","targetForm":"innocent","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"inherit":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"继承"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"遗传"}],"examples":[{"sentence":"So Americans are lucky that they have inherited the innovations of the past, and that real incomes will continue to grow in the future.","translation":"因此，美国人是幸运的，他们继承过去了的创新，真实收入在未来也将继续上升。","targetForm":"inherited","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Anna's striking almond-shaped eyes, inherited from her Asian lineage, exude a captivating depth and a hint of mystery.","translation":"安娜引人注目的杏仁状眼睛继承了她的亚洲血统，散发着迷人的深度和一丝神秘感。","targetForm":"inherited","senseId":"source-v-2","sourceSenseId":"v-2"}]},"inspect":{"senseGroups":[{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"检验"}],"examples":[{"sentence":"Everything has been suspected and been inspected; thoughts have no boundaries.","translation":"所有的事物都要被怀疑、被验证，思想没有界限。","targetForm":"inspected","senseId":"source-v-3","sourceSenseId":"v-3"}]},"injury":{"senseGroups":[{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"损伤","contextReviewed":true}],"examples":[{"sentence":"I got hurt during an experiment, and the injury was pretty serious.","translation":"我做实验的时候弄伤了，而且还伤得十分严重。","targetForm":"injury","senseId":"source-n-4","sourceSenseId":"n-4"}]},"innovation":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"创新"}],"examples":[{"sentence":"But while these innovations are certainly significant, they are only a fraction of what is possible.","translation":"这些创新固然十分重要，却只发挥了一小部分潜力而已。","targetForm":"innovations","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"That leads to the challenge of effective management of public assets – management that promotes rather than impedes market efficiency and innovation.","translation":"这就提出了对公共资产进行有效管理的挑战 — — 这种管理应该促进而不是妨碍市场效率和创新。","targetForm":"innovation","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"If we want to reverse these trends and maximize innovation output, we need more mechanisms for funding the commercialization of smart ideas.","translation":"如果想扭转上述趋势并最大限度地提高创新产出，我们需要更多机制来为聪明的理念提供商业化资助。","targetForm":"innovation","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Thanks to lower oil prices, innovation, and economies of scale in the renewable-energy sector, that vision can now be turned into reality.","translation":"多亏油价下跌、创新和可再生能源领域的规模经济，我们现在可以实现这样的目标。","targetForm":"innovation","senseId":"source-n-2","sourceSenseId":"n-2"}]},"include":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"包括"}],"examples":[{"sentence":"That is the most important message for everyone, atheists included, to take from the Christian story of Christmas.","translation":"所有人，包括无神论者，都应该从基督的圣诞故事中领会这种最重要的精神涵义。","targetForm":"included","senseId":"source-v-1","sourceSenseId":"v-1"}]},"insect":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"昆虫"}],"examples":[{"sentence":"My family's cat is not afraid of people or insects, but is afraid of chicks.","translation":"我家的猫不怕人，不怕虫子，就怕小鸡。","targetForm":"insects","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The insect grew out of a pupa into an imago.","translation":"昆虫破蛹而出变成成虫。","targetForm":"insect","senseId":"source-n-1","sourceSenseId":"n-1"}]}}};
